<script lang="ts">
	// @ts-nocheck
	import { onMount } from 'svelte'
	import { smart_api } from '../lib/smart-api'
	let metrics = $state(null), error = $state(''), granularity = $state('daily'), loading = $state(false)
	async function load() { loading = true; error = ''; try { metrics = await smart_api.get_metrics(granularity) } catch (err) { error = err instanceof Error ? err.message : String(err) } finally { loading = false } }
	onMount(() => { void load() })
	const percent = (value: number) => `${Math.round((value || 0) * 100)}%`
	const cost = (value: number) => String(value || 0)
	const series = () => metrics?.series || []
	const max_cost = () => Math.max(...series().map((item) => Number(item.provider_cost || 0)), 0.000001)
	const max_total = () => Math.max(...series().map((item) => Number(item.total || 0)), 1)
	function cost_points() { const values = series(); if (!values.length) return ''; const width = 700, height = 190, left = 18, bottom = 18; return values.map((item, index) => { const x = values.length === 1 ? width / 2 : left + index * ((width - left * 2) / (values.length - 1)); const y = height - bottom - (Number(item.provider_cost || 0) / max_cost()) * (height - bottom - 12); return `${x.toFixed(1)},${y.toFixed(1)}` }).join(' ') }
	function set_granularity(value) { granularity = value; void load() }
</script>

<section class="page"><header class="heading"><div><p>Task performance</p><h2>Execution metrics</h2><span>Monitor SMART run volume, outcomes, and reported cost over time.</span></div><button class="refresh" onclick={() => load()} disabled={loading}>{loading ? 'Refreshing…' : 'Refresh'}</button></header>{#if error}<p class="error">{error}</p>{/if}
	{#if metrics}<section class="cards"><article><span>Total tasks</span><strong>{metrics.total}</strong></article><article><span>Success rate</span><strong>{percent(metrics.success_rate)}</strong><small>{metrics.successful} successful / {metrics.terminal} completed</small></article><article><span>Running</span><strong>{metrics.running}</strong></article><article><span>Average duration</span><strong>{metrics.average_duration_ms ? `${Math.round(metrics.average_duration_ms / 1000)}s` : '—'}</strong></article><article><span>Cost</span><strong>{cost(metrics.provider_cost_total)}</strong><small>Reported workflow cost</small></article></section>
		<section class="card charts"><div class="chart-head"><div><h3>Execution trend</h3><p>Choose the time bucket used by both charts.</p></div><div class="granularity" role="group" aria-label="Metrics grouping">{#each [['hourly','Hourly'],['daily','Daily'],['weekly','Weekly'],['monthly','Monthly']] as [value,label]}<button class:active={granularity === value} onclick={() => set_granularity(value)}>{label}</button>{/each}</div></div>{#if series().length}<div class="chart-grid"><article class="chart"><div class="chart-title"><div><h4>Cost over time</h4><span>Reported workflow cost</span></div><strong>{cost(metrics.provider_cost_total)}</strong></div><div class="line-wrap"><svg viewBox="0 0 700 210" preserveAspectRatio="none" aria-label="Cost line chart" role="img"><line x1="18" y1="192" x2="682" y2="192" class="axis" /><line x1="18" y1="102" x2="682" y2="102" class="gridline" /><polyline points={cost_points()} class="cost-line" />{#each series() as item, index (item.label)}{@const point = cost_points().split(' ')[index]?.split(',') || []}{#if point.length}<circle cx={point[0]} cy={point[1]} r="3.6" class="cost-point"><title>{item.label}: {cost(item.provider_cost)}</title></circle>{/if}{/each}</svg></div><div class="labels">{#each series() as item (item.label)}<span title={item.label}>{item.label}</span>{/each}</div></article>
			<article class="chart"><div class="chart-title"><div><h4>Outcome volume</h4><span>Successful and failed tasks</span></div><div class="legend"><i class="success"></i>Success <i class="failed"></i>Failed</div></div><div class="stack-wrap">{#each series() as item (item.label)}<div class="stack-column" title={`${item.label}: ${item.success} success, ${item.failed} failed`}><div class="stack"><i class="failed" style={`height:${(Number(item.failed || 0) / max_total()) * 100}%`}></i><i class="success" style={`height:${(Number(item.success || 0) / max_total()) * 100}%`}></i></div><span>{item.success + item.failed}</span></div>{/each}</div><div class="labels">{#each series() as item (item.label)}<span title={item.label}>{item.label}</span>{/each}</div></article></div>{:else}<p class="empty">No task data for this time range yet.</p>{/if}</section>
	{:else}<div class="card loading">Loading metrics…</div>{/if}</section>
<style>.page{width:min(1180px,100%);margin:0 auto;display:grid;gap:1rem}.heading{display:flex;justify-content:space-between;gap:1rem;align-items:end}.heading p,.heading h2,.heading span{margin:0}.heading p{color:var(--accent-color,#3159db);font-size:.72rem;font-weight:650;letter-spacing:.08em;text-transform:uppercase}.heading h2{margin:.2rem 0;font-size:1.45rem;font-weight:560;letter-spacing:-.03em}.heading span,.cards span,small,.empty,.chart-title span,.chart-head p{color:var(--muted-ink-color,#637083);font-size:.8rem}button{border:0;border-radius:8px;padding:.62rem .8rem;color:#fff;background:var(--accent-color,#3159db);font:inherit;font-weight:600;cursor:pointer}button:disabled{opacity:.65;cursor:default}.cards{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:1rem}.cards article,.card{border:1px solid var(--border-color,#dbe2ec);border-radius:14px;padding:1rem;background:var(--panel-background,#fff)}.cards article{display:grid;gap:.32rem}.cards strong{font-size:1.3rem;font-weight:600}.charts{padding:1.15rem}.chart-head,.chart-title{display:flex;justify-content:space-between;gap:1rem;align-items:flex-start}.chart-head h3,.chart-head p,.chart-title h4,.chart-title span{margin:0}.chart-head h3{font-size:1rem}.chart-head p{margin-top:.2rem}.granularity{display:flex;gap:.3rem;padding:.25rem;border:1px solid #e0e7f0;border-radius:9px;background:#f8faff}.granularity button{padding:.38rem .58rem;color:#627187;background:transparent;font-size:.75rem}.granularity button.active{color:#3159db;background:#edf2ff;box-shadow:0 1px 2px #25324613}.chart-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem;margin-top:1rem}.chart{min-width:0;padding:.9rem;border:1px solid #e2e8f0;border-radius:11px;background:#fcfdff}.chart-title h4{font-size:.88rem}.chart-title strong{font-size:.88rem;font-weight:600}.line-wrap{height:220px;margin-top:.6rem;padding:.4rem .1rem 0}.line-wrap svg{width:100%;height:100%;overflow:visible}.axis{stroke:#dce4ef;stroke-width:1}.gridline{stroke:#edf1f5;stroke-width:1;stroke-dasharray:4 4}.cost-line{fill:none;stroke:#5270e8;stroke-width:2.6;stroke-linecap:round;stroke-linejoin:round}.cost-point{fill:#fff;stroke:#5270e8;stroke-width:2}.labels{display:grid;grid-template-columns:repeat(auto-fit,minmax(44px,1fr));gap:.25rem;margin-top:.15rem}.labels span{overflow:hidden;color:#7a8798;font-size:.66rem;text-align:center;text-overflow:ellipsis;white-space:nowrap}.legend{display:flex;align-items:center;gap:.3rem;color:#68768a;font-size:.7rem}.legend i{width:8px;height:8px;border-radius:3px}.legend i.success,.stack i.success{background:#45a97c}.legend i.failed,.stack i.failed{background:#df6f7b}.stack-wrap{display:flex;align-items:end;justify-content:space-around;gap:.45rem;height:220px;margin-top:.6rem;padding:.4rem .65rem 0;border-bottom:1px solid #dce4ef}.stack-column{display:grid;flex:1;min-width:16px;height:100%;grid-template-rows:1fr auto;align-items:end;gap:.35rem}.stack{display:flex;flex-direction:column-reverse;justify-content:flex-start;width:100%;height:100%;overflow:hidden;border-radius:5px 5px 0 0;background:#f0f3f7}.stack i{display:block;min-height:0;transition:height .2s}.stack-column>span{color:#69778b;font-size:.68rem;text-align:center}.error{margin:0;padding:.75rem;border-radius:9px;color:var(--danger-color,#cc3b45);background:#fff0f1}.loading{color:var(--muted-ink-color,#637083)}@media(max-width:940px){.cards{grid-template-columns:repeat(2,minmax(0,1fr))}.chart-grid{grid-template-columns:1fr}.chart-head{align-items:stretch;flex-direction:column}.granularity{width:fit-content}}@media(max-width:540px){.heading{align-items:stretch;flex-direction:column}.cards{grid-template-columns:1fr}.granularity{width:100%;overflow:auto}.labels span{font-size:.6rem}}</style>
